stack <int> sk;
vector <int> vec[2][N];

void mofen(int pos, int val){
	for (pos += 5; pos < N; pos += pos & - pos)
		fen[pos] = min(fen[pos], val);
}
int gefen(int pos){
	int res = n + 1;
	for (pos += 5; 0 < pos; pos -= pos & - pos)
		res = min(res, fen[pos]);
	return res;
}

void find_3412(){
	fill(fen, fen + n + 10, n + 1);
	while (!sk.empty())
		sk.pop();
	for (int i = 1; i <= n; ++ i){
		while (!sk.empty() && a[i] < a[sk.top()])
			sk.pop();
		if (!sk.empty())
			vec[0][sk.top()].push_back(i);
		sk.push(i);
	}
	while (!sk.empty())
		sk.pop();
	for (int i = n; 1 <= i; -- i){
		while (!sk.empty() && a[sk.top()] < a[i])
			sk.pop();
		if (!sk.empty())
			vec[1][sk.top()].push_back(i);
		sk.push(i);
	}
	for (int i = n; 1 <= i; -- i){
		for (int ind : vec[0][i])
			mofen(a[ind], ind);
		for (int ind : vec[1][i])
			min_r[ind] = min(min_r[ind], gefen(a[ind] - 1));
		vec[0][i].clear(), vec[1][i].clear();
	}
}

int main(){
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

	cin >> n;
	for (int i = 1; i <= n; ++ i)
