	for (int i = 1; i <= n; ++ i)
		a[i] = n + 1 - a[i];
	find_3412();
	for (int i = n; 1 <= i; -- i){
		min_r[i] = min(min_r[i], min_r[i + 1]);
		ans += min_r[i] - i;
	}
	cout << ans << '\n';

	return 0;
}

