const int N = 200200;
int n;
char s[N];
int bal[N];
int pos[N];

void solve() {
	scanf("%d %s", &n, s);
	int b = 0;
	for (int i = 0; i < n; i++) {
		if (s[i] == '0')
			b++;
		else
			b--;
	}
	if (b < 0) {
		for (int i = 0; i < n; i++)
			s[i] ^= 1;
		reverse(s, s + n);
		b *= -1;
	}
	bal[0] = (n + b) / 2;
	for (int i = 0; i < n; i++)
		bal[i + 1] = bal[i] + (s[i] == '0' ? -1 : 1);
	assert(bal[n] == (n - b) / 2);
	for (int i = 0; i <= n; i++)
		pos[i] = -1;
	for (int i = 0; i <= n; i++)
		pos[bal[i]] = i;
	int ans = 0;
	int l = 0;
	while(l < (n + b) / 2) {
		if (bal[l + 1] < bal[l]) {
			l++;
			continue;
		}
		if (bal[l] <= (n - b) / 2) {
			ans++;
			break;
		}
		int r = pos[bal[l]];
		assert(r > l);
		ans++;
		for (int i = l + 1; i < r; i++) {
			if (2 * i > l + r) {
				bal[i] = bal[l] - (r - i);
			} else {
				bal[i] = bal[l] - (i - l);
			}
			pos[bal[i]] = max(pos[bal[i]], i);
		}
	}
	printf("%d\n", ans);
}

